import type { DialogRootProps } from "@kobalte/core/dialog";
import { cn } from "~/lib/utils.ts";
import IconSearch01 from "~icons/hugeicons/search-01";
import IconTick02 from "~icons/hugeicons/tick-02";

import * as CommandPrimitive from "cmdk-solid";
import type {
  Component,
  ComponentProps,
  ParentProps,
  VoidProps,
} from "solid-js";

import { mergeProps, splitProps } from "solid-js";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "./dialog.tsx";
import { InputGroup, InputGroupAddon } from "./input-group.tsx";

const Command: Component<ParentProps<CommandPrimitive.CommandRootProps>> = (
  props,
) => {
  const [local, others] = splitProps(props, ["class"]);

  return (
    <CommandPrimitive.CommandRoot
      data-slot="command"
      class={cn(
        "bg-popover text-popover-foreground rounded-none flex size-full flex-col overflow-hidden",
        local.class,
      )}
      {...others}
    />
  );
};

type CommandDialogProps = ParentProps<DialogRootProps> & {
  title?: string;
  description?: string;
  class?: string;
  showCloseButton?: boolean;
};

const CommandDialog: Component<CommandDialogProps> = (rawProps) => {
  const props = mergeProps(
    {
      title: "Command Palette",
      description: "Search for a command to run...",
      showCloseButton: false,
    },
    rawProps,
  );
  const [local, others] = splitProps(props, [
    "title",
    "description",
    "children",
    "class",
    "showCloseButton",
  ]);

  return (
    <Dialog {...others}>
      <DialogHeader class="sr-only">
        <DialogTitle>{local.title}</DialogTitle>
        <DialogDescription>{local.description}</DialogDescription>
      </DialogHeader>
      <DialogContent
        class={cn(
          "rounded-none top-1/3 translate-y-0 overflow-hidden p-0",
          local.class,
        )}
        showCloseButton={local.showCloseButton}
      >
        {local.children}
      </DialogContent>
    </Dialog>
  );
};

const CommandInput: Component<VoidProps<CommandPrimitive.CommandInputProps>> = (
  props,
) => {
  const [local, others] = splitProps(props, ["class"]);

  return (
    <div data-slot="command-input-wrapper" class="border-b pb-0">
      <InputGroup class="bg-input/30 border-input/30 h-8 border-none shadow-none! *:data-[slot=input-group-addon]:pl-2!">
        <CommandPrimitive.CommandInput
          data-slot="command-input"
          class={cn(
            "w-full text-xs outline-hidden disabled:cursor-not-allowed disabled:opacity-50",
            local.class,
          )}
          {...others}
        />
        <InputGroupAddon>
          <IconSearch01
            class="size-4 shrink-0 opacity-50"
          />
        </InputGroupAddon>
      </InputGroup>
    </div>
  );
};

const CommandList: Component<ParentProps<CommandPrimitive.CommandListProps>> = (
  props,
) => {
  const [local, others] = splitProps(props, ["class"]);

  return (
    <CommandPrimitive.CommandList
      data-slot="command-list"
      class={cn(
        "no-scrollbar max-h-72 scroll-py-0 outline-none overflow-y-auto overflow-x-hidden",
        local.class,
      )}
      {...others}
    />
  );
};

const CommandEmpty: Component<ParentProps<CommandPrimitive.CommandEmptyProps>> =
  (props) => {
    const [local, others] = splitProps(props, ["class"]);

    return (
      <CommandPrimitive.CommandEmpty
        data-slot="command-empty"
        class={cn("py-6 text-center text-xs", local.class)}
        {...others}
      />
    );
  };

const CommandGroup: Component<ParentProps<CommandPrimitive.CommandGroupProps>> =
  (props) => {
    const [local, others] = splitProps(props, ["class"]);

    return (
      <CommandPrimitive.CommandGroup
        data-slot="command-group"
        class={cn(
          "text-foreground **:[[cmdk-group-heading]]:text-muted-foreground overflow-hidden **:[[cmdk-group-heading]]:px-2 **:[[cmdk-group-heading]]:py-1.5 **:[[cmdk-group-heading]]:text-xs",
          local.class,
        )}
        {...others}
      />
    );
  };

const CommandSeparator: Component<
  VoidProps<CommandPrimitive.CommandSeparatorProps>
> = (props) => {
  const [local, others] = splitProps(props, ["class"]);

  return (
    <CommandPrimitive.CommandSeparator
      data-slot="command-separator"
      class={cn("bg-border -mx-1 h-px", local.class)}
      {...others}
    />
  );
};

const CommandItem: Component<ParentProps<CommandPrimitive.CommandItemProps>> = (
  props,
) => {
  const [local, others] = splitProps(props, ["class", "children"]);

  return (
    <CommandPrimitive.CommandItem
      data-slot="command-item"
      class={cn(
        "data-[selected=true]:bg-muted relative flex cursor-default items-center gap-2 rounded-none px-2 py-2 text-xs outline-hidden select-none in-data-[slot=dialog-content]:rounded-none! [&_svg:not([class*='size-'])]:size-4 data-[selected=true]:text-foreground data-[selected=true]:*:[svg]:text-foreground group/command-item [&_svg]:pointer-events-none data-[disabled=true]:pointer-events-none [&_svg]:shrink-0 data-[disabled=true]:opacity-50",
        local.class,
      )}
      {...others}
    >
      {local.children}
      <IconTick02
        class="ml-auto opacity-0 group-has-data-[slot=command-shortcut]/command-item:hidden group-data-[checked=true]/command-item:opacity-100"
      />
    </CommandPrimitive.CommandItem>
  );
};

const CommandShortcut: Component<ComponentProps<"span">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);

  return (
    <span
      data-slot="command-shortcut"
      class={cn(
        "text-muted-foreground group-data-[selected=true]/command-item:text-foreground ml-auto text-xs tracking-widest",
        local.class,
      )}
      {...others}
    />
  );
};

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
};
